"""Derive SkyyRebirth/build_skyyrebirth_0.3.1.py from SkyyRebirth/build_skyyrebirth_0.3.py (= the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_3_patch.py). rep(old, new) with asserted anchors; 0.3 stays untouched; its line endings are kept; every change is checked at
the end to prove nothing else changed.
Run:  python tools/rebirth_0_3_1_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.3.1.py   (NO --deploy: coordinated deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.3.1.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every new code path executed)

0.3.1 (2026-10-14) = ECONOMY ROUND econ38, the SkyyRebirth part (Skyy 2026-10-14 "Run everything you can in parallel. I want everything on
your list done by 5 pm" - the RESUME Next list). THE WHOLE FEATURE STAYS OFF (rebirth.on=false), as in 0.3:
  (1) /rebirthadmin crashtest <n> | points <arm|all> <n|reset> | refund <arm|all> PARSE NOW. 0.3 had ONE usage variant taking a
      GREEDY_STRING, and the engine picks a usage variant by the NUMBER of words, so every two- or three-word line was refused by the
      game's own parser ("wrong number of required parameters"; quoted, the value kept its quotes) - found by the admin-page round
      (tools/menu_0_3_23_patch.py notes). Now they are SUB-COMMANDS with their own arguments, the way SkyyAuctions' /ahadmin regrant /
      closeall work (each requirePermission("skyyrebirth.admin")): crashtest <point: whole number>, points <arm> <n or reset>,
      refund <arm>. Each passes the same line to RbAdmin.run as 0.3 did (the same rules, answers and the twice-in-10-s confirm). The
      one-word lines (status, dryrun, rebirth, recover, backups, help) keep 0.3's usage variant; bare /rebirthadmin = help + status.
  (2) THE FARMING ARM IS FED BY FARMING + RANCHING + ORCHARD (research/Gathering-Shards-Spec.md 5.3: "Farming splits into Farming,
      Ranching and Orchard (three skills, one shared tree; your Farming level = their average)"; SkyySkills 0.4.37 made the two new
      skills): the arm's progress = (run XP of Farming + Ranching + Orchard) / (XP to the cap of the three) - i.e. the average of the
      three pools, matching "your Farming level = their average". The points formula is unchanged (floor(B x sqrt(progress)), under
      25 % pays 0, B = 8). Both places that count points use it:
        - the /rebirth preview (RbCheck.gains): skill:fn:run for "farming", "ranching" and "orchard" (SkyySkills 0.4.37+ answers all
          three; an older SkyySkills answers only Farming = 0.3's number);
        - the decision (RbTx.decide, from the PREPARED facts only - what recovery sees): arm.farming + arm.ranching + arm.orchard
          (SkyySkills 0.4.38+ writes the last two; a rebirth prepared by 0.4.37 has arm.farming only = 0.3's number).
      RbMath.armAdd adds two pools (run + XP-to-cap; the level / cap shown stay Farming's), saturating at Long.MAX_VALUE.
  Every rebirth participant contract is unchanged (rebirth:part:skills / coins / bank ops and answers, the journal, rebirth:fn:* keys).
  ROLLBACK to 0.3: safe (no saved-data change; the Farming arm counts Farming alone again; /rebirthadmin crashtest stops parsing).
"""
import difflib
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.py")
dst = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.1.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.3"
s = raw.decode("utf8").replace("\r\n", "\n")
LF = "\n"
S0 = s
assert 'VERSION = "0.3"' in s and "GENERATED by tools/rebirth_0_3_patch.py" in s and "armAdd" not in s, "not the generated 0.3"
OLDS = []


def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.1 (2026-10-14)"):].rstrip() + "\n"

# ---------------------------------------------------------------- docstring + version
rep('''"""SkyyRebirth 0.3 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_patch.py from build_skyyrebirth_0.2.py (itself''',
    '''"""SkyyRebirth 0.3.1 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_1_patch.py from build_skyyrebirth_0.3.py (itself
generated by tools/rebirth_0_3_patch.py from 0.2,''')
rep('''Run:   python SkyyRebirth/build_skyyrebirth_0.3.py   -> SkyyRebirth/SkyyRebirth-0.3.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)
''', '''Run:   python SkyyRebirth/build_skyyrebirth_0.3.1.py   -> SkyyRebirth/SkyyRebirth-0.3.1.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.1.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''' + NOTE + '''  CHECKED: SkyyRebirth/test_skyyrebirth_0.3.1.py.
''')
rep('VERSION = "0.3"\n', 'VERSION = "0.3.1"\n')
rep('''             (PGM, "getCustomPage"), (T["PAGE"], "onDismiss"), (T["PAGE"], "sendUpdate")):''',
    '''             (PGM, "getCustomPage"), (T["PAGE"], "onDismiss"), (T["PAGE"], "sendUpdate"),
             # 0.3.1: the /rebirthadmin sub-commands (crashtest / points / refund) and their argument types
             ("com.hypixel.hytale.server.core.command.system.AbstractCommand", "addSubCommand"), (T["ATY"], "INTEGER"), (T["ATY"], "STRING")):''')

# ---------------------------------------------------------------- (2) RbMath.armAdd (pure)
rep('''# spec 3.3 (Skyy Q7): the bank bonus of ONE rebirth in parts per million''',
    '''# 0.3.1: the Farming arm = Farming + Ranching + Orchard. Two pools {run, toCap, level, cap} -> one: run XP and XP-to-cap added (saturating
# at Long.MAX_VALUE), the level / cap of the first (Farming) kept; a missing pool (null) counts nothing. points() then sees the share of
# the three pools together = their average when the caps match.
F(mth, 'public static final String FARM_ARM = "farming";')
F(mth, 'public static final String[] FARM_POOLS = new String[] { "ranching", "orchard" };')
M(mth, r"""
public static long satAdd(long a, long b) {
  if (a < 0L) a = 0L;
  if (b < 0L) b = 0L;
  long r = a + b;
  return r < 0L ? Long.MAX_VALUE : r;
}""")
M(mth, r"""
public static long[] armAdd(long[] a, long[] b) {
  if (a == null) return b;
  if (b == null || b.length < 4 || a.length < 4) return a;
  return new long[] { satAdd(a[0], b[0]), satAdd(a[1], b[1]), a[2], a[3] };
}""")
# spec 3.3 (Skyy Q7): the bank bonus of ONE rebirth in parts per million''')

# ---------------------------------------------------------------- (2) the preview: RbCheck.runFarm + gains
rep('''# ms left in combat (SkyySkills skill:fn:combat), -1 = unknown (no SkyySkills)''',
    '''# 0.3.1: the Farming arm's preview = skill:fn:run of Farming + Ranching + Orchard (an older SkyySkills answers Farming only = 0.3's
# number); same Object[] shape as run() (level, cap, run XP, XP to the cap) or null when Farming itself has no answer
M(chk, r"""
public static long[] runArr(Object[] r) {
  if (r == null || r.length < 4 || !(r[2] instanceof Number) || !(r[3] instanceof Number)) return null;
  long lv = r[0] instanceof Number ? ((Number) r[0]).longValue() : 0L;
  long cp = r[1] instanceof Number ? ((Number) r[1]).longValue() : 0L;
  return new long[] { ((Number) r[2]).longValue(), ((Number) r[3]).longValue(), lv, cp };
}""")
M(chk, r"""
public static Object[] runFarm(java.util.UUID u) {
  Object[] f = run(u, @PKG@.RbMath.FARM_ARM);
  long[] a = runArr(f);
  if (a == null) return f;
  for (int j = 0; j < @PKG@.RbMath.FARM_POOLS.length; j++) a = @PKG@.RbMath.armAdd(a, runArr(run(u, @PKG@.RbMath.FARM_POOLS[j])));
  return new Object[] { f[0], f[1], Long.valueOf(a[0]), Long.valueOf(a[1]) };
}""")
# ms left in combat (SkyySkills skill:fn:combat), -1 = unknown (no SkyySkills)''')
rep('''    if (!maxed) r = run(u, @PKG@.RbMath.ARM_SKILL[i]);''',
    '''    if (!maxed) r = @PKG@.RbMath.FARM_ARM.equals(@PKG@.RbMath.ARM_SKILL[i]) ? runFarm(u) : run(u, @PKG@.RbMath.ARM_SKILL[i]);   // 0.3.1: Farming = 3 pools''')

# ---------------------------------------------------------------- (2) the decision: arm.farming + arm.ranching + arm.orchard (prepared facts)
rep('''    long[] a = arm(sk.getProperty("arm." + @PKG@.RbMath.ARM_SKILL[i]));
''', '''    long[] a = arm(sk.getProperty("arm." + @PKG@.RbMath.ARM_SKILL[i]));
    if (a != null && @PKG@.RbMath.FARM_ARM.equals(@PKG@.RbMath.ARM_SKILL[i])) {   // 0.3.1: + Ranching + Orchard (SkyySkills 0.4.38+ facts)
      for (int j = 0; j < @PKG@.RbMath.FARM_POOLS.length; j++) a = @PKG@.RbMath.armAdd(a, arm(sk.getProperty("arm." + @PKG@.RbMath.FARM_POOLS[j])));
    }
''')

# ---------------------------------------------------------------- (1) /rebirthadmin sub-commands crashtest / points / refund
SUBS = r'''# 0.3.1: crashtest / points / refund as SUB-COMMANDS (the engine picks a usage variant by its word count, so 0.3's one GREEDY_STRING
# variant refused every 2- and 3-word line). Each builds the same line 0.3's variant passed to RbAdmin.run (same rules and answers).
admx = mk("RbAdminCrashCmd", T["APC"])
F(admx, "public @RA@ pointArg;")
C(admx, r"""
public RbAdminCrashCmd() {
  super("crashtest", "(admin) a rebirth of YOUR active profile that stops after point 0-7 (like a crash) - type it twice within 10 s");
  requirePermission("skyyrebirth.admin");
  this.pointArg = withRequiredArg("point", "0 BEGIN ... 7 DONE", @ATY@.INTEGER);
}""")
M(admx, r"""
protected void execute(@CTX@ ctx, @ST@ store, @REF@ ref, @PR@ pr, @WLD@ world) {
  try { @PKG@.RbAdmin.send(pr, @PKG@.RbAdmin.run(pr.getUuid(), "crashtest " + String.valueOf(ctx.get(this.pointArg)), System.currentTimeMillis())); }
  catch (Throwable t) { @PKG@.RbCfg.warn("/rebirthadmin crashtest failed: " + t); try { pr.sendMessage(@MSG@.raw("[Rebirth] /rebirthadmin failed - see the server log.").color("#ff6b6b")); } catch (Throwable t2) { } }
}""")
admp = mk("RbAdminPointsCmd", T["APC"])
F(admp, "public @RA@ armArg;")
F(admp, "public @RA@ nArg;")
C(admp, r"""
public RbAdminPointsCmd() {
  super("points", "(admin) test rebirth points on YOUR active profile: points <arm|all> <1-100000|reset>");
  requirePermission("skyyrebirth.admin");
  this.armArg = withRequiredArg("arm", "Class, Foraging, Mining, Smithing, Alchemy, Farming, Fishing, Cooking or all", @ATY@.STRING);
  this.nArg = withRequiredArg("n", "1-100000 points, or reset", @ATY@.STRING);
}""")
M(admp, r"""
protected void execute(@CTX@ ctx, @ST@ store, @REF@ ref, @PR@ pr, @WLD@ world) {
  try { @PKG@.RbAdmin.send(pr, @PKG@.RbAdmin.run(pr.getUuid(), "points " + String.valueOf(ctx.get(this.armArg)) + " " + String.valueOf(ctx.get(this.nArg)), System.currentTimeMillis())); }
  catch (Throwable t) { @PKG@.RbCfg.warn("/rebirthadmin points failed: " + t); try { pr.sendMessage(@MSG@.raw("[Rebirth] /rebirthadmin failed - see the server log.").color("#ff6b6b")); } catch (Throwable t2) { } }
}""")
admf = mk("RbAdminRefundCmd", T["APC"])
F(admf, "public @RA@ armArg;")
C(admf, r"""
public RbAdminRefundCmd() {
  super("refund", "(admin) refund the rebirth tree points of an arm on YOUR active profile: refund <arm|all>");
  requirePermission("skyyrebirth.admin");
  this.armArg = withRequiredArg("arm", "Class, Foraging, Mining, Smithing, Alchemy, Farming, Fishing, Cooking or all", @ATY@.STRING);
}""")
M(admf, r"""
protected void execute(@CTX@ ctx, @ST@ store, @REF@ ref, @PR@ pr, @WLD@ world) {
  try { @PKG@.RbAdmin.send(pr, @PKG@.RbAdmin.run(pr.getUuid(), "refund " + String.valueOf(ctx.get(this.armArg)), System.currentTimeMillis())); }
  catch (Throwable t) { @PKG@.RbCfg.warn("/rebirthadmin refund failed: " + t); try { pr.sendMessage(@MSG@.raw("[Rebirth] /rebirthadmin failed - see the server log.").color("#ff6b6b")); } catch (Throwable t2) { } }
}""")
admc = mk("RbAdminCmd", T["APC"])'''
rep('''admc = mk("RbAdminCmd", T["APC"])''', SUBS)
rep('''  requirePermission("skyyrebirth.admin");
  addUsageVariant(new @PKG@.RbAdminArgsCmd());
}""")''', '''  requirePermission("skyyrebirth.admin");
  addUsageVariant(new @PKG@.RbAdminArgsCmd());
  addSubCommand(new @PKG@.RbAdminCrashCmd());    // 0.3.1
  addSubCommand(new @PKG@.RbAdminPointsCmd());
  addSubCommand(new @PKG@.RbAdminRefundCmd());
}""")''')
rep('''ALL = [cfg, load, st, mth, tree, rbj, jrn, fnc, pub, tick, chk, tel, tx, run_, page, job, rfr, cmd, adm, admv, admc, pl]''',
    '''ALL = [cfg, load, st, mth, tree, rbj, jrn, fnc, pub, tick, chk, tel, tx, run_, page, job, rfr, cmd, adm, admv, admx, admp, admf, admc, pl]   # 0.3.1: + 3 sub-commands''')
rep('''+ "), the rebirth tree (" + @PKG@.RbTree.NID.length + " nodes;''',
    '''+ "), the rebirth tree (" + @PKG@.RbTree.NID.length + " nodes; the Farming arm counts Farming + Ranching + Orchard;''')

# ---------------------------------------------------------------- checks
assert s.index("public static long[] armAdd(") < s.index("public static Object[] runFarm(") < s.index("runFarm(u) : run(u,")
assert s.index("public static long[] armAdd(") < s.index("a = @PKG@.RbMath.armAdd(a, arm(")
assert s.index('admx = mk("RbAdminCrashCmd"') < s.index('admc = mk("RbAdminCmd"') < s.index("addSubCommand(new @PKG@.RbAdminCrashCmd());")
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3,", len(_gone), "0.3 lines replaced;", len(OLDS), "anchors")
